package teks

// Balik membalik urutan karakter s. Ia bekerja per rune, bukan per byte,
// supaya huruf beraksen tidak tercabik jadi byte tak bermakna.
func Balik(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

