func main() {
	// Bagian 1: WaitGroup + Mutex
	var wg sync.WaitGroup
	var mu sync.Mutex
	hasil := make([]int, 0, 8)

	for i := 1; i <= 8; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			kuadrat := n * n
			mu.Lock()
			hasil = append(hasil, kuadrat)
			mu.Unlock()
		}(i)
	}
	wg.Wait()

	sort.Ints(hasil)
	fmt.Println("Kuadrat:", hasil)

	// Bagian 2: channel berpenyangga
	ch := make(chan int, 8)
	go func() {
		defer close(ch)
		for i := 1; i <= 8; i++ {
			ch <- i * i
		}
	}()

	total := 0
	for n := range ch {
		total += n
	}
	fmt.Println("Total dari channel:", total)
}

